    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '101: A woman at 35 weeks with pre-eclampsia without severe features has reached her "recommended" delivery time. What is it?', '["37 weeks 0 days", "38 weeks 0 days", "39 weeks 0 days", "40 weeks 0 days"]', 0, 'ACOG recommends delivery at 37 weeks for pre-eclampsia without severe features. (ACOG)'),
    (v_topic_id, '102: What is the "maintenance dose" of Magnesium Sulfate for seizure prophylaxis in pre-eclampsia?', '["1 g/hour", "2 g/hour", "4 g/hour", "5 g/hour"]', 1, 'Standard is 4-6g load followed by 1-2g/hour. (Williams)'),
    (v_topic_id, '103: Which of the following is a contraindication to Magnesium Sulfate use?', '["Hypertension", "Myasthenia Gravis", "Diabetes", "Asthma"]', 1, 'Magnesium can precipitate a myasthenic crisis by inhibiting acetylcholine release. (Gabbe)'),
    (v_topic_id, '104: A woman with GDM has well-controlled blood sugars on DIET alone. When is delivery recommended?', '["37 weeks", "39 weeks to 40 weeks 6 days", "42 weeks", "Induction at 38 weeks"]', 1, 'Expectant management until 39+ weeks is appropriate if sugars are controlled. (ACOG)'),
    (v_topic_id, '105: A woman with GDM requiring INSULIN for control should be delivered by:', '["37 weeks 0 days", "39 weeks 0-6 days", "38 weeks 0-6 days", "40 weeks 0-6 days"]', 1, 'Delivery is recommended between 39w0d and 39w6d for insulin-controlled GDM. (ACOG)'),
    (v_topic_id, '106: What is the recommended follow-up test for GDM at 4-12 weeks postpartum?', '["HbA1c", "Random blood glucose", "75-gram 2-hour Oral Glucose Tolerance Test (OGTT)", "100-gram 3-hour OGTT"]', 2, 'To screen for persistent Type 2 Diabetes or impaired glucose tolerance. (ACOG)'),
    (v_topic_id, '107: "Vaginal Birth After Cesarean" (VBAC) is associated with what risk of uterine rupture in a woman with one prior low-transverse incision?', '["0.1%", "0.5-0.9%", "5%", "10%"]', 1, 'While low, it is a significant consideration for counseling. (ACOG)'),
    (v_topic_id, '108: Which of the following is an absolute contraindication to a trial of labor after Cesarean (TOLAC)?', '["Prior classical incision", "Prior T-shaped uterine incision", "History of uterine rupture", "All of the above"]', 3, 'These carry a much higher risk of rupture (up to 10-12%). (Williams)'),
    (v_topic_id, '109: A woman at 32 weeks has a "Preterm Labor" diagnosis. She is GBS positive. What should she receive?', '["Steroids and Tocolytics only", "Steroids, Tocolytics, and GBS prophylaxis (Penicillin)", "Steroids and GBS prophylaxis only", "Induction of labor"]', 1, 'Intrapartum GBS prophylaxis is indicated if delivery is likely. (CDC)'),
    (v_topic_id, '110: "Nifedipine" (Calcium channel blocker) used for tocolysis has what common maternal side effect?', '["Tachycardia and hypotension", "Hypoglycemia", "Constipation", "Hyperkalemia"]', 0, 'Due to peripheral vasodilation. (Beckmann)'),
    (v_topic_id, '111: Which tocolytic is associated with "Oligohydramnios" and "closure of the ductus" if used too long?', '["Nifedipine", "Indomethacin", "Terbutaline", "Atosiban"]', 1, 'Indomethacin reduces fetal urine output. (Gabbe)'),
    (v_topic_id, '112: In "PPROM" at < 34 weeks, why is "Latency Antibiotics" (e.g., Ampicillin/Erythromycin) given?', '["To treat chorioamnionitis", "To prolong the latency period (time to delivery) and reduce neonatal morbidity", "To prevent GBS only", "To induce labor"]', 1, 'Shows a significant reduction in neonatal infections and RDS. (Williams)'),
    (v_topic_id, '113: A "Negative" fFN test is most helpful because it indicates:', '["The baby is definitely healthy", "The woman is 99% unlikely to deliver in the next 7 days", "The cervix is long", "Labor has started"]', 1, 'Excellent negative predictive value. (ACOG)'),
    (v_topic_id, '114: "Cervical Length" measurement on ultrasound is a screen for preterm birth. A length < ____ mm is considered a risk factor.', '["15 mm", "25 mm", "35 mm", "40 mm"]', 1, 'Values below 20-25 mm between 16-24 weeks increase the risk of PTB. (Gabbe)'),
    (v_topic_id, '115: "Vaginal Progesterone" is indicated in which of the following women?', '["History of preterm birth", "Short cervix (< 20 mm) discovered incidentally on ultrasound", "Twins", "Triplets"]', 1, 'Helps reduce the risk of PTB in asymptomatic women with a short cervix. (ACOG)'),
    (v_topic_id, '116: "17-alpha-hydroxyprogesterone caproate" (17-OHP) injections were traditionally used for:', '["Women with a history of spontaneous preterm birth", "GDM control", "Stopping active labor", "Hypertension"]', 0, 'Recent studies have questioned its efficacy, and some manufacturers have withdrawn it. (FDA/ACOG)'),
    (v_topic_id, '117: What is the most common presentation of a "Monochorionic/Diamniotic" twin pregnancy?', '["One placenta, one sac", "One placenta, two sacs", "Two placentas, two sacs", "Two placentas, one sac"]', 1, 'The most common type of identical twins. (Williams)'),
    (v_topic_id, '118: "Monochorionic" twins require ultrasound every 2 weeks starting at 16 weeks to screen for:', '["Down syndrome", "Twin-to-Twin Transfusion Syndrome (TTTS)", "Gestational diabetes", "Breech"]', 1, 'Early detection is critical for fetoscopic laser treatment. (ACOG)'),
    (v_topic_id, '119: "Twin Anemia-Polycythemia Sequence" (TAPS) is a variant of TTTS characterized by:', '["Large fluid difference", "Hemoglobin difference without large fluid difference", "Fused sacs", "Both twins being anemic"]', 1, 'Due to small vascular anastomoses. (Gabbe)'),
    (v_topic_id, '120: What is the "Quintero Staging" used for?', '["Pre-eclampsia", "TTTS severity", "Cervical dilation", "Fetal growth"]', 1, 'Stage I (fluid) to Stage V (death of one/both). (Williams)'),
    (v_topic_id, '121: "Discordant Growth" in twins is usually defined as a difference in estimated fetal weight of > ____ %.', '["10%", "20%", "30%", "50%"]', 1, 'Requires closer monitoring for IUGR in the smaller twin. (ACOG)'),
    (v_topic_id, '122: In a twin pregnancy where Twin A is Vertex and Twin B is Breech, what is the preferred mode of delivery?', '["C-section for both", "Vaginal delivery of Twin A, followed by a trial of vaginal delivery or breech extraction of Twin B", "Internal version of Twin A", "Wait for Twin B to turn"]', 1, 'Commonly managed vaginally in experienced centers. (ACOG)'),
    (v_topic_id, '123: If Twin A is BREECH, what is the recommended mode of delivery?', '["Vaginal delivery", "Cesarean section", "Wait for labor", "External version during labor"]', 1, 'C-section is recommended if the first twin is not vertex. (ACOG)'),
    (v_topic_id, '124: "Umbilical Artery Doppler" showing Reversed End-Diastolic Flow (REDF) is an indication for:', '["Expectant management", "Delivery (usually by C-section if at a viable age)", "Wait 1 week", "Aspirin"]', 1, 'High risk of imminent fetal demise. (Gabbe)'),
    (v_topic_id, '125: "Asymmetric IUGR" (Head Sparing) indicates that fetal growth restriction began:', '["In the 1st trimester", "In the late 2nd or 3rd trimester", "At fertilization", "Postpartum"]', 1, 'Usually due to uteroplacental insufficiency. (Williams)'),
    (v_topic_id, '126: "Symmetric IUGR" is more commonly associated with:', '["Hypertension", "Chromosomal anomalies or early TORCH infections", "Smoking", "Poor nutrition"]', 1, 'The growth restriction occurs globally during early development. (Beckmann)'),
    (v_topic_id, '127: What is the primary concern with "Polyhydramnios" during labor?', '["Fetal distress", "Umbilical cord prolapse upon ROM", "Shoulder dystocia", "Pre-eclampsia"]', 1, 'The sudden rush of fluid can carry the cord down. (Williams)'),
    (v_topic_id, '128: "Placenta Previa" bleeding is usually:', '["Painful and dark", "Painless and bright red", "Brownish discharge", "Minimal"]', 1, 'The bleeding is maternal in origin. (Beckmann)'),
    (v_topic_id, '129: A woman at 32 weeks has a "Marginal Previa" (placenta < 2cm from os). She wants a vaginal delivery. Is it possible?', '["No, must be C-section", "Yes, a trial of vaginal delivery is often successful if the placenta is > 1-2 cm from the os", "Only if it''s a breech", "Only with twins"]', 1, 'Many marginal previas migrate or allow for a safe vaginal birth. (ACOG)'),
    (v_topic_id, '130: "Accreta Spectrum" is most commonly diagnosed prenatally via:', '["Physical exam", "Ultrasound with Doppler (showing lacunae and loss of retroplacental clear zone)", "CT scan", "Lab tests"]', 1, 'MRI can be a helpful adjunct but US is first-line. (ACOG)'),
    (v_topic_id, '131: "Placental Abruption" is a "clinical" diagnosis. Does a normal ultrasound rule it out?', '["Yes", "No, ultrasound only detects 25-50% of abruptions", "Only if it''s a large abruption", "None of the above"]', 1, 'Management is based on clinical signs (pain, bleeding, fetal distress). (Williams)'),
    (v_topic_id, '132: A woman at 38 weeks has a "Grade 1" (mild) abruption. The fetal heart rate is reassuring. Management?', '["Immediate C-section", "Vaginal delivery (induction if not in labor)", "Wait until 41 weeks", "Bed rest at home"]', 1, 'Vaginal delivery is preferred if both mother and fetus are stable. (Gabbe)'),
    (v_topic_id, '133: A "Sinusoidal" fetal heart rate pattern is often seen in severe cases of:', '["Vasa previa rupture (fetal exsanguination)", "Rh alloimmunization", "Placental abruption", "All of the above"]', 3, 'Indicates severe fetal anemia or hypoxia. (ACOG)'),
    (v_topic_id, '134: In "Vasa Previa," the vessels are at risk of rupture because they are:', '["Too thick", "Running through the membranes without Wharton''s jelly (velamentous insertion)", "Connected to the mother", "In the way of the baby"]', 1, 'Commonly associated with succenturiate lobes. (Beckmann)'),
    (v_topic_id, '135: What is the classic finding of "Uterine Rupture" during labor?', '["Fetal bradycardia and "loss of station" (head moves up)", "Heavy vaginal bleeding", "High fever", "Polyhydramnios"]', 0, 'The presenting part recedes into the abdomen. (ACOG)'),
    (v_topic_id, '136: A woman with "Asthma" is having a PPH. Which medication is specifically contraindicated?', '["Oxytocin", "Methylergonovine", "15-methyl prostaglandin F2-alpha (Hemabate)", "Misoprostol"]', 2, 'It can trigger severe bronchospasm. (Williams)'),
    (v_topic_id, '137: "Methylergonovine" (Methergine) should be avoided in women with:', '["Asthma", "Hypertension or Pre-eclampsia", "Diabetes", "Penicillin allergy"]', 1, 'It is an ergot alkaloid that causes peripheral vasoconstriction. (ACOG)'),
    (v_topic_id, '138: What is the most effective INITIAL treatment for "Uterine Atony"?', '["Uterine massage and Oxytocin", "Hysterectomy", "Aspirin", "Antibiotics"]', 0, 'Bimanual massage helps stimulate contractions. (Beckmann)'),
    (v_topic_id, '139: "Bakri Balloon" is used in the management of PPH to:', '["Induce labor", "Tamponade the uterine cavity and stop bleeding from the placental site", "Ripen the cervix", "Measure blood loss"]', 1, 'An effective non-surgical intervention. (Gabbe)'),
    (v_topic_id, '140: A woman has a PPH. After massage and oxytocin, her BP is 150/100. Which drug is preferred next?', '["Methergine", "Hemabate or Misoprostol", "Labetalol", "Warfarin"]', 1, 'Methergine is avoided due to the BP. (ACOG)'),
    (v_topic_id, '141: "Uterine Inversion" is often associated with:', '["Excessive traction on the umbilical cord during the 3rd stage of labor", "Large baby", "Prior C-section", "Post-term"]', 0, 'Pulling on the cord before the placenta has detached. (Williams)'),
    (v_topic_id, '142: "Amniotic Fluid Embolism" (AFE) often occurs:', '["In the 1st trimester", "During labor, delivery, or immediately postpartum", "At 20 weeks", "Only in smokers"]', 1, 'A rare, catastrophic inflammatory response. (ACOG)'),
    (v_topic_id, '143: DIC in AFE is characterized by:', '["High fibrinogen", "Low platelets, low fibrinogen, and prolonged PT/PTT", "High platelets", "Normal labs"]', 1, 'Severe consumptive coagulopathy. (Gabbe)'),
    (v_topic_id, '144: A pregnant woman has "Acute Appendicitis." Where is the pain most likely to be located in the 3rd trimester?', '["Right lower quadrant", "Right upper quadrant", "Left lower quadrant", "Periumbilical"]', 1, 'The growing uterus displaces the appendix upward and laterally. (Williams)'),
    (v_topic_id, '145: "Pyelonephritis" in pregnancy is more likely to cause which complication?', '["Maternal sepsis", "Preterm labor", "ARDS (Acute Respiratory Distress Syndrome)", "All of the above"]', 3, 'Endotoxins affect the alveolar-capillary membrane. (Beckmann)'),
    (v_topic_id, '146: What is the most common cause of "fetal tachycardia" (FHR > 160)?', '["Fetal distress", "Maternal fever/infection", "Fetal sleep", "Maternal hypertension"]', 1, 'Often the first sign of chorioamnionitis. (ACOG)'),
    (v_topic_id, '147: "Chorioamnionitis" is treated with which antibiotics?', '["Ampicillin and Gentamicin", "Clindamycin and Gentamicin", "Vancomycin", "Metronidazole"]', 0, 'Broad-spectrum coverage for vaginal and enteric flora. (Williams)'),
    (v_topic_id, '148: A woman at 38 weeks has GBS bacteriuria. Does she need a GBS screen at 36 weeks?', '["Yes", "No, she automatically requires intrapartum prophylaxis", "Only if she has symptoms", "Only if it''s her first baby"]', 1, 'GBS in the urine at any concentration indicates heavy colonization. (CDC)'),
    (v_topic_id, '149: "Listeriosis" in pregnancy can present with:', '["A "flu-like" illness in the mother", "Brown-stained amniotic fluid", "Neonatal granulomatosis infantiseptica", "All of the above"]', 3, 'Requires treatment with Ampicillin. (Gabbe)'),
    (v_topic_id, '150: "Primary" CMV infection in pregnancy carries what risk of vertical transmission?', '["1%", "10%", "30-40%", "100%"]', 2, 'Higher risk than recurrent/secondary infections. (Williams)'),
    (v_topic_id, '151: "Congenital CMV" is the leading cause of non-hereditary:', '["Blindness", "Sensorineural hearing loss", "Heart defects", "Limb defects"]', 1, 'May be progressive after birth. (CDC)'),
    (v_topic_id, '152: Maternal "Toxoplasmosis" is most commonly acquired via:', '["Undercooked meat or cat feces", "Unwashed fruit", "Infected water", "All of the above"]', 3, 'Spiramycin can be used to reduce transmission. (Gabbe)'),
    (v_topic_id, '153: A woman at 32 weeks has "HELLP Syndrome." Her BP is 150/95. What is the management?', '["Steroids and wait 48 hours", "Immediate stabilization and delivery", "Oral antihypertensives and home monitoring", "Wait until 37 weeks"]', 1, 'HELLP is a severe feature; delivery is indicated regardless of gestational age (usually once stabilized). (ACOG)'),
    (v_topic_id, '154: "Eclampsia" can occur how long after delivery?', '["Only before birth", "Up to 4-6 weeks postpartum (Late postpartum eclampsia)", "Only in the 1st hour", "None of the above"]', 1, 'Most occur within 48 hours, but late cases are well-documented. (Williams)'),
    (v_topic_id, '155: A "Low" Bishop Score (e.g., 3) in a woman needing induction should be managed with:', '["Immediate Oxytocin", "Cervical ripening (e.g., Misoprostol or Foley balloon)", "C-section", "Wait 1 week"]', 1, 'Oxytocin is less successful with an unfavorable cervix. (ACOG)'),
    (v_topic_id, '156: "Postpartum Blues" usually peak at day ____ and resolve by day ____.', '["1; 3", "5; 10-14", "10; 30", "None"]', 1, 'Affects up to 80% of women; self-limiting. (Beckmann)'),
    (v_topic_id, '157: "Postpartum Depression" is distinguished from "Blues" by:', '["Presence of sadness", "Symptoms lasting > 2 weeks and functional impairment", "Fatigue", "Anxiety"]', 1, 'Requires screening (e.g., Edinburgh Postnatal Depression Scale). (ACOG)'),
    (v_topic_id, '158: In "Gestational Transient Thyrotoxicosis," the TSH is low because:', '["The thyroid is failing", "hCG has TSH-like activity and stimulates T4, which suppresses TSH", "Maternal age", "Iodine deficiency"]', 1, 'Usually occurs in the 1st trimester and resolves without treatment. (Gabbe)'),
    (v_topic_id, '159: Which heart condition carries the HIGHEST risk of maternal mortality (~25-50%)?', '["Mitral valve prolapse", "Eisenmenger syndrome (Pulmonary hypertension)", "Atrial septal defect", "Mild aortic stenosis"]', 1, 'Pregnancy is often strictly contraindicated in women with severe pulmonary HTN. (Williams)'),
    (v_topic_id, '160: A woman with a "Mechanical Heart Valve" should be on which anticoagulant in the 1st trimester?', '["Warfarin (if dose < 5mg)", "LMWH (Enoxaparin)", "Aspirin", "Both A and B are options depending on counseling"]', 3, 'Warfarin is the best for the valve but a teratogen; management is complex. (ACOG)'),
    (v_topic_id, '161: "Prurigo of Pregnancy" presents with:', '["Itchy papules on the extensor surfaces of the limbs", "Blisters around the umbilicus", "Jaundice", "Hair loss"]', 0, 'A benign dermatosis of pregnancy. (Beckmann)'),
    (v_topic_id, '162: "PUPPP" lesions typically SPARE which area?', '["The abdomen", "The umbilicus", "The thighs", "The arms"]', 1, 'This helps differentiate it from Pemphigoid Gestationis. (Gabbe)'),
    (v_topic_id, '163: "Intrahepatic Cholestasis of Pregnancy" is characterized by the elevation of:', '["ALT/AST only", "Total Bile Acids", "Bilirubin only", "Alkaline phosphatase (which is normally high in pregnancy)"]', 1, 'Bile acids > 10-40 umol/L. (ACOG)'),
    (v_topic_id, '164: A "Complete Mole" has a risk of developing into Choriocarcinoma of about:', '["1%", "15-20%", "50%", "100%"]', 1, 'Requires careful hCG follow-up. (Williams)'),
    (v_topic_id, '165: "Partial Moles" often present with:', '["Extremely high hCG", "A missed abortion or non-viable fetus", "Hyperemesis", "Snowstorm only"]', 1, 'hCG levels are usually lower than in complete moles. (Beckmann)'),
    (v_topic_id, '166: "Choriocarcinoma" is unique among cancers for being extremely responsive to:', '["Surgery only", "Chemotherapy (Methotrexate)", "Radiation", "Immunotherapy"]', 1, 'Cure rates are high even with metastases. (Gabbe)'),
    (v_topic_id, '167: What is the standard duration of contraception after a molar pregnancy?', '["1 month", "6-12 months (until hCG is zero for a period of time)", "None", "5 years"]', 1, 'To avoid confusing a new pregnancy with persistent GTN. (ACOG)'),
    (v_topic_id, '168: A woman at 38 weeks has "decreased fetal movement." What is the first-line evaluation?', '["Immediate C-section", "Non-Stress Test (NST) and Amniotic Fluid Index (AFI)", "Wait 24 hours", "Kick counts at home only"]', 1, 'Requires objective assessment of fetal well-being. (ACOG)'),
    (v_topic_id, '169: A "Category III" fetal heart rate tracing indicates:', '["Reassuring status", "Indeterminate status", "Abnormal status with high risk of fetal acidemia", "Normal labor"]', 2, 'Includes absent variability with late/variable decelerations or bradycardia. (ACOG)'),
    (v_topic_id, '170: "Vibroacoustic Stimulation" is used during an NST to:', '["Wake the fetus and elicit accelerations", "Start contractions", "Induce labor", "Measure fetal hearing"]', 0, 'Helps reduce the time to a reactive test. (Beckmann)'),
    (v_topic_id, '171: A "Biophysical Profile" (BPP) of 6/10 at 38 weeks should be managed with:', '["Reassurance", "Delivery", "Repeat in 1 week", "Bed rest"]', 1, 'Equivocal score at term usually warrants delivery. (ACOG)'),
    (v_topic_id, '172: Which component of the BPP is the first to disappear with acute hypoxia?', '["Amniotic fluid volume", "Fetal heart rate reactivity (NST)", "Fetal breathing movements", "Fetal tone"]', 1, 'The CNS-mediated parameters are lost sequentially. (Gabbe)'),
    (v_topic_id, '173: "Oligohydramnios" (AFI < 5) is a sign of ____ hypoxia.', '["Acute", "Chronic", "No", "Postpartum"]', 1, 'Reflects decreased fetal renal perfusion over time. (Williams)'),
    (v_topic_id, '174: Maternal "Smoking" is a risk factor for:', '["IUGR", "SIDS", "Placental abruption", "All of the above"]', 3, 'Strongly discouraged in prenatal care. (CDC)'),
    (v_topic_id, '175: "Fetal Hydantoin Syndrome" is caused by maternal use of:', '["Alcohol", "Phenytoin", "Warfarin", "Lithium"]', 1, 'Characterized by craniofacial anomalies and hypoplastic nails. (Beckmann)'),
    (v_topic_id, '176: "Ebstein Anomaly" (tricuspid valve defect) is associated with maternal use of:', '["Alcohol", "Lithium", "Valproic acid", "ACE inhibitors"]', 1, 'Classic board-exam association, though the absolute risk is small. (Gabbe)'),
    (v_topic_id, '177: Maternal "Valproic Acid" use in the 1st trimester is associated with a 1-2% risk of:', '["Heart defects", "Neural tube defects (e.g., Spina bifida)", "Limb defects", "Cleft lip"]', 1, 'Folic acid supplements should be increased (4mg). (ACOG)'),
    (v_topic_id, '178: "Thalidomide" embryopathy is classic for:', '["Heart defects", "Phocomelia (limb reduction)", "Blindness", "Deafness"]', 1, 'Historic example of teratogenicity. (Williams)'),
    (v_topic_id, '179: A "Grade 3" placental abruption involves:', '["Small amount of bleeding", "Partial separation with fetal distress", "Complete separation with fetal death and maternal coagulopathy", "None of the above"]', 2, 'The most severe form. (Gabbe)'),
    (v_topic_id, '180: "Kleihauer-Betke" test measures the resistance of ____ to acid elution.', '["Maternal hemoglobin (HbA)", "Fetal hemoglobin (HbF)", "Platelets", "Albumin"]', 1, 'HbF remains while HbA is "ghosted." (Beckmann)'),
    (v_topic_id, '181: A woman at 41 weeks has an AFI of 3 cm. Management?', '["Wait until 42 weeks", "Induction of labor", "C-section only", "Oral hydration and recheck in 3 days"]', 1, 'Oligohydramnios is an indication for delivery in a post-term pregnancy. (ACOG)'),
    (v_topic_id, '182: "Post-maturity Syndrome" infants appear:', '["Fat", "Thin, with peeling skin, long nails, and meconium staining", "Normal", "Edematous"]', 1, 'Due to placental insufficiency. (Williams)'),
    (v_topic_id, '183: What is the most common cause of "arrest of progress" in the first stage of labor?', '["Fetal size", "Inadequate uterine contractions (power)", "Maternal age", "Position of the baby"]', 1, 'Often managed with oxytocin augmentation. (ACOG)'),
    (v_topic_id, '184: "Cephalopelvic Disproportion" (CPD) is diagnosed when:', '["The baby is too big for the mother''s pelvis", "The cervix won''t dilate despite adequate contractions", "The baby is breech", "None of the above"]', 1, 'Often requires a Cesarean section. (Beckmann)'),
    (v_topic_id, '185: A "Shoulder Dystocia" is suspected when you see the:', '["Turtle sign" (head retracts against the perineum)]', '["Turtle sign", "Lizard sign", "Rabbit sign", "Bird sign"]', 0, 'Indicates the shoulder is impacted behind the symphysis. (Williams)'),
    (v_topic_id, '186: "Erb''s Palsy" (Waiters tip) involves injury to which nerve roots?', '["C3-C4", "C5-C6", "C8-T1", "L4-L5"]', 1, 'Can occur during a difficult delivery with shoulder dystocia. (Gabbe)'),
    (v_topic_id, '187: "Klumpke''s Palsy" (Claw hand) involves injury to which nerve roots?', '["C5-C6", "C8-T1", "L1-L2", "T10-T12"]', 1, 'Often includes Horner''s syndrome if T1 is involved. (Beckmann)'),
    (v_topic_id, '188: What is the "McRoberts Maneuver"?', '["Hyperflexion of maternal hips onto the abdomen", "Suprapubic pressure", "Rotation of the fetus", "Cutting the perineum"]', 0, 'Standard first-line maneuver for shoulder dystocia. (ACOG)'),
    (v_topic_id, '189: "Suprapubic pressure" is applied in shoulder dystocia to:', '["Push the baby out", "Dislodge the anterior shoulder from behind the symphysis", "Slow the delivery", "Prevent bleeding"]', 1, 'Pressure is applied over the pubic bone, not the fundus. (Williams)'),
    (v_topic_id, '190: "Postpartum Hemorrhage" is defined as a drop in hematocrit of > ____ % or the need for transfusion.', '["5%", "10%", "20%", "50%"]', 1, 'Traditional definition; clinical EBL is more commonly used now. (Beckmann)'),
    (v_topic_id, '191: Which "T" of PPH involves a "retained placenta"?', '["Tone", "Trauma", "Tissue", "Thrombin"]', 2, 'Requires manual extraction or D&C. (ACOG)'),
    (v_topic_id, '192: "Amniotic Fluid Embolism" is most similar to which of the following processes?', '["Septic shock", "Anaphylaxis or Systemic Inflammatory Response Syndrome (SIRS)", "Heart attack", "Stroke"]', 1, 'A massive immune/inflammatory reaction. (Gabbe)'),
    (v_topic_id, '193: "Sheehan Syndrome" presents with:', '["Failure to lactate and amenorrhea", "Excessive milk production", "High blood pressure", "Weight gain"]', 0, 'Due to ischemia of the anterior pituitary. (Williams)'),
    (v_topic_id, '194: "Endometritis" is more common after:', '["Vaginal delivery", "Cesarean delivery (especially if following labor/ROM)", "1st trimester miscarriage", "Exercise"]', 1, 'Introduction of vaginal flora into the uterus during surgery. (ACOG)'),
    (v_topic_id, '195: A breastfeeding mother has "Mastitis." She should:', '["Stop breastfeeding to let the breast rest", "Continue breastfeeding or pumping to drain the breast", "Take aspirin only", "Switch to formula"]', 1, 'Drainage is essential for cure and to prevent abscess. (Beckmann)'),
    (v_topic_id, '196: "Galactocele" is a:', '["Breast infection", "Benign milk-filled cyst", "Breast cancer", "Hormonal imbalance"]', 1, 'Usually painless and diagnosed by ultrasound or aspiration. (Gabbe)'),
    (v_topic_id, '197: "Rhogam" (Rho(D) immune globulin) should be given within ____ hours of delivery.', '["1 hour", "24 hours", "72 hours", "1 week"]', 2, 'Standard window for prophylaxis. (ACOG)'),
    (v_topic_id, '198: A "Sinusoidal" fetal heart rate pattern that is PERSISTENT is a Category ____ tracing.', '["I", "II", "III", "IV"]', 2, 'Requires immediate evaluation and likely delivery. (ACOG)'),
    (v_topic_id, '199: "Cervical Ripening" is contraindicated in women with:', '["Prior classical C-section", "Prior myomectomy entering the cavity", "Placenta previa", "All of the above"]', 3, 'Standard contraindications to labor apply to ripening. (Williams)'),
    (v_topic_id, '200: "Misoprostol" (Cytotec) is a prostaglandin ____ analogue.', '["E1", "E2", "F2-alpha", "I2"]', 0, 'Widely used for ripening and PPH. (Beckmann)');
